import React, { useEffect, useMemo, useState } from "react";
import "@/answer-ai.css";
import { startLogin } from "@/const";
import { useAuth } from "@/_core/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { WrongQuestionAiExplanation } from "@/components/WrongQuestionAiExplanation";
import { OfficialV2Explanation } from "@/components/OfficialV2Explanation";
import { CsvExportAdvancedControls } from "@/components/CsvExportAdvancedControls";
import { toast } from "sonner";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { trpc } from "@/lib/trpc";
import { getStarredQuestionIds } from "@/lib/starred";
import { getOfficialV2Explanation } from "@/lib/explanationDisplay";
import { ALL_COURSE_TYPES, excludeAnsweredQuestions, filterQuestionsByCourse, getCourseTypes, getWeakestCourse, selectSequentialPracticeQuestions, selectSmartPracticeQuestions, sortCourseTypes, type CourseSort } from "@/lib/courseTypes";
import { getStartupStatus } from "@shared/startupState";
import { summarizeWrongProgress } from "@shared/wrongProgress";
import { ALL_SUBCATEGORIES, filterQuestionsBySubcategory, getSubcategories, getWeakestSubcategory } from "@/lib/subcategories";
import { ADMIN_PENDING_QUICK_FILTERS, filterAdminPendingQuestions, getAdminPendingQuickFilterCounts, type AdminPendingQuickFilter } from "@/lib/adminPendingFilters";
import { buildPendingQuestionsCsv } from "@/lib/adminPendingExport";
import { filterWrongQuestions, filterWrongQuestionsMissingConcise, getMostRecentWrongQuestion, getOfficialOptionPreview, getPreviousQuestionCursor, getQuestionTextSummary, getSelectedOptionForQuestion, getWrongQuestionForReplay } from "@/lib/wrongQuestionBook";
import { downloadWrongQuestionPdf } from "@/lib/wrongQuestionPdf";
import { downloadWrongQuestionCsv, estimateWrongQuestionCsv, filterWrongQuestionCsvItems, formatWrongQuestionCsvSize, getDefaultWrongQuestionCsvColumns, readWrongQuestionCsvPresets, renameWrongQuestionCsvPreset, serializeWrongQuestionCsvPresets, WRONG_QUESTION_CSV_COLUMNS, type WrongQuestionCsvColumnKey, type WrongQuestionCsvPreset, type WrongQuestionCsvStatus } from "@/lib/wrongQuestionCsv";
import { SITE_MAIN_TITLE, SITE_SUBTITLE } from "@/lib/siteIdentity";
import { ArrowRight, BookOpenCheck, BrainCircuit, CheckCircle2, ChevronDown, ChevronLeft, CircleAlert, Download, Flag, Flame, History, Home as HomeIcon, LogIn, RefreshCw, RotateCcw, Settings, ShieldCheck, Shuffle, Sparkles, Star, Target, ThumbsUp, Undo2, XCircle } from "lucide-react";

type Section = "home" | "quiz" | "wrong" | "starred" | "issues" | "stats" | "admin" | "settings";
type Mode = "practice" | "mock" | "wrong" | "starred";
type QuestionOrder = "random" | "sequential";

type Answer = { questionId: string; sequenceNo: number; selectedOption: "A" | "B" | "C" | "D"; correctOption: "A" | "B" | "C" | "D"; isCorrect: boolean; markedReviewError?: string };

const optionLabels = { A: "A", B: "B", C: "C", D: "D" } as const;

export default function Home() {
  const { user, loading, logout, refresh } = useAuth();
  const { data, error: bootstrapError, isLoading, refetch: refetchBootstrap } = trpc.quiz.bootstrap.useQuery(undefined, { retry: 1, refetchOnWindowFocus: false });
  const [startupTimedOut, setStartupTimedOut] = useState(false);
  useEffect(() => {
    if (!loading && !isLoading) { setStartupTimedOut(false); return; }
    const timeoutId = window.setTimeout(() => setStartupTimedOut(true), 12000);
    return () => window.clearTimeout(timeoutId);
  }, [loading, isLoading]);
  const startupStatus = getStartupStatus({ authLoading: loading, bootstrapLoading: isLoading, bootstrapError: Boolean(bootstrapError), timedOut: startupTimedOut });
  const requestedView = new URLSearchParams(window.location.search).get("view");
  const requestedMode = new URLSearchParams(window.location.search).get("mode");
  const [section, setSection] = useState<Section>(() => ["quiz", "wrong", "starred", "issues", "stats", "admin", "settings"].includes(requestedView ?? "") ? requestedView as Section : "home");
  const [mode, setMode] = useState<Mode>(() => ["practice", "mock", "wrong", "starred"].includes(requestedMode ?? "") ? requestedMode as Mode : "practice");
  const [count, setCount] = useState(5);
  const [questionOrder, setQuestionOrder] = useState<QuestionOrder>("sequential");
  const [excludeTested, setExcludeTested] = useState(false);
  const [courseType, setCourseType] = useState(ALL_COURSE_TYPES);
  const [subcategory, setSubcategory] = useState(ALL_SUBCATEGORIES);
  const [courseSort, setCourseSort] = useState<CourseSort>("default");
  const [starTagFilter, setStarTagFilter] = useState("全部");
  const [activeQuestions, setActiveQuestions] = useState<any[]>([]);
  const [cursor, setCursor] = useState(0);
  const [answers, setAnswers] = useState<Answer[]>([]);
  const [selected, setSelected] = useState<keyof typeof optionLabels | null>(null);
  const [finished, setFinished] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [wrongFilter, setWrongFilter] = useState<"待複習" | "已熟悉" | "全部" | "未解析">("待複習");
  const [aiExplanationByQuestion, setAiExplanationByQuestion] = useState<Record<string, any>>({});
  const [aiExplanationTarget, setAiExplanationTarget] = useState<string | null>(null);
  const [answerAiExplanationByQuestion, setAnswerAiExplanationByQuestion] = useState<Record<string, any>>({});
  const [answerAiExplanationTarget, setAnswerAiExplanationTarget] = useState<string | null>(null);
  const [isExportingWrongPdf, setIsExportingWrongPdf] = useState(false);
  const [isExportingWrongCsv, setIsExportingWrongCsv] = useState(false);
  const [fontScale, setFontScale] = useState(() => Number(localStorage.getItem("sep4-font-scale") || "1"));
  const [density, setDensity] = useState<"comfortable" | "compact">(() => localStorage.getItem("sep4-density") === "compact" ? "compact" : "comfortable");
  useEffect(() => { localStorage.setItem("sep4-font-scale", String(fontScale)); }, [fontScale]);
  useEffect(() => { localStorage.setItem("sep4-density", density); }, [density]);
  const questions = data?.questions ?? [];
  const officialConcise = trpc.quiz.officialConciseList.useQuery();
  const officialConciseByQuestion = useMemo(() => Object.fromEntries((officialConcise.data ?? []).map((row: any) => [row.questionId, row])) as Record<string, any>, [officialConcise.data]);
  const current = activeQuestions[cursor];
  const history = trpc.attempts.history.useQuery(undefined, { enabled: Boolean(user) });
  const answeredQuestionIds = trpc.attempts.answeredQuestionIds.useQuery(undefined, { enabled: Boolean(user) });
  const stats = trpc.attempts.stats.useQuery(undefined, { enabled: Boolean(user) });
  const courseProgress = trpc.attempts.courseProgress.useQuery(undefined, { enabled: Boolean(user) });
  const subcategoryProgress = trpc.attempts.subcategoryProgress.useQuery(undefined, { enabled: Boolean(user) });
  const learningGoal = trpc.attempts.learningGoal.useQuery(undefined, { enabled: Boolean(user) });
  const wrong = trpc.wrongQuestions.list.useQuery(undefined, { enabled: Boolean(user) });
  const wrongProgress = useMemo(() => summarizeWrongProgress(wrong.data ?? []), [wrong.data]);
  const conciseNotes = trpc.wrongQuestions.conciseList.useQuery(undefined, { enabled: Boolean(user) });
  const wrongPdfData = trpc.wrongQuestions.exportPdfData.useQuery(undefined, { enabled: false });
  const utils = trpc.useUtils();
  const recordCsvExport = trpc.wrongQuestions.recordCsvExport.useMutation({ onSuccess: () => utils.wrongQuestions.csvExportHistory.invalidate() });
  const starred = trpc.starredQuestions.list.useQuery(undefined, { enabled: Boolean(user) });
  const questionIssues = trpc.questionIssues.list.useQuery(undefined, { enabled: Boolean(user) });
  const issueIds = useMemo(() => new Set((questionIssues.data ?? []).map((row: any) => row.questionId)), [questionIssues.data]);
  const starredIds = useMemo(() => new Set((starred.data ?? []).map((row: any) => row.questionId)), [starred.data]);
  const starTags = useMemo(() => Array.from(new Set((starred.data ?? []).map((row: any) => row.tag).filter(Boolean))).sort() as string[], [starred.data]);
  const filteredStarredIds = useMemo(() => getStarredQuestionIds(starred.data ?? [], starTagFilter), [starred.data, starTagFilter]);
  const conciseByQuestion = useMemo(() => Object.fromEntries((conciseNotes.data ?? []).map((row: any) => [row.questionId, row])) as Record<string, any>, [conciseNotes.data]);
  const concisePendingCount = useMemo(() => (wrong.data ?? []).filter((row: any) => !conciseByQuestion[row.questionId]).length, [wrong.data, conciseByQuestion]);
  const recentWrongQuestion = useMemo(() => getMostRecentWrongQuestion(wrong.data ?? []), [wrong.data]);
  const starredStats = trpc.starredQuestions.stats.useQuery(undefined, { enabled: Boolean(user) });
  const courseTypes = useMemo(() => getCourseTypes(questions), [questions]);
  const sortedCourseTypes = useMemo(() => sortCourseTypes(courseTypes, courseProgress.data, courseSort), [courseTypes, courseProgress.data, courseSort]);
  const subcategories = useMemo(() => getSubcategories(questions, courseType), [questions, courseType]);
  useEffect(() => { if (subcategory !== ALL_SUBCATEGORIES && !subcategories.some(item => item.id === subcategory)) setSubcategory(ALL_SUBCATEGORIES); }, [subcategory, subcategories]);
  const filtered = useMemo(() => {
    const modePool = mode === "starred" ? questions.filter((q: any) => filteredStarredIds.has(q.id)) : questions;
    const coursePool = filterQuestionsBySubcategory(filterQuestionsByCourse(modePool, courseType), subcategory);
    if (mode === "practice" && excludeTested && user) {
      return excludeAnsweredQuestions(coursePool, answeredQuestionIds.data ?? []);
    }
    return coursePool;
  }, [questions, courseType, subcategory, mode, filteredStarredIds, excludeTested, user, answeredQuestionIds.data]);
  const complete = trpc.attempts.complete.useMutation({ onSuccess: value => { setResult(value); setFinished(true); history.refetch(); wrong.refetch(); starredStats.refetch(); courseProgress.refetch(); subcategoryProgress.refetch(); } });
  const toggleStar = trpc.starredQuestions.toggle.useMutation({ onSuccess: () => starred.refetch() });
  const toggleQuestionIssue = trpc.questionIssues.toggle.useMutation({ onSuccess: () => questionIssues.refetch(), onError: () => toast.error("問題標記未完成", { description: "請稍後再試，原本的題庫資料不會變更。" }) });
  const updateStarTag = trpc.starredQuestions.updateTag.useMutation({ onSuccess: () => starred.refetch() });
  const updateStarReminder = trpc.starredQuestions.updateReminder.useMutation({ onSuccess: () => { starred.refetch(); starredStats.refetch(); } });
  const updateLearningGoal = trpc.attempts.updateLearningGoal.useMutation({ onSuccess: () => learningGoal.refetch() });
  const explainWrongQuestion = trpc.wrongQuestions.explain.useMutation({ onSuccess: value => { setAiExplanationByQuestion(current => ({ ...current, [value.questionId]: value })); setAiExplanationTarget(null); }, onError: () => { setAiExplanationTarget(null); toast.error("AI 解析暫時無法取得", { description: "請稍後再試；官方答案與解析仍可直接查看。" }); } });
  const generateConciseNotes = trpc.wrongQuestions.generateConciseBatch.useMutation({ onSuccess: value => { conciseNotes.refetch(); toast.success("精簡解析已更新", { description: `已產生 ${value.generatedCount} 題${value.failedCount ? `，${value.failedCount} 題暫時失敗` : ""}；尚有 ${value.remainingCount} 題待補齊。` }); }, onError: () => toast.error("精簡解析暫時無法產生", { description: "請稍後再試；官方答案與解析不受影響。" }) });
  const rateConciseNote = trpc.wrongQuestions.rateConcise.useMutation({ onSuccess: value => { conciseNotes.refetch(); toast.success(value.regenerated ? "已重新產生精簡解析" : "已記錄你的回饋", { description: value.regenerated ? "新版本已保存到你的錯題本。" : "之後會依這類回饋持續調整呈現方式。" }); }, onError: () => toast.error("回饋處理未完成", { description: "請稍後再試；原本已儲存的解析仍保留。" }) });
  const markWrongMastered = trpc.wrongQuestions.markMastered.useMutation({ onSuccess: value => { wrong.refetch(); toast.success("已標記為已熟悉", { description: `${value.questionId} 已移至已熟悉清單，仍可於全部清單回顧。` }); }, onError: () => toast.error("標記未完成", { description: "請稍後再試；原本的錯題狀態仍保留。" }) });
  const explainQuizAnswer = trpc.quiz.explainAnswer.useMutation({ onSuccess: value => { setAnswerAiExplanationByQuestion(current => ({ ...current, [value.questionId]: value })); setAnswerAiExplanationTarget(null); }, onError: () => { setAnswerAiExplanationTarget(null); toast.error("AI 解析暫時無法取得", { description: "請稍後再試；官方答案與解析仍可直接查看。" }); } });
  const analyzePdfWeakness = trpc.wrongQuestions.analyzePdfWeakness.useMutation();
  const exportWrongQuestionPdf = async (onlyConcise = false) => {
    if (!user) { startLogin(); return; }
    setIsExportingWrongPdf(true);
    try {
      const result = await wrongPdfData.refetch();
      if (result.error) throw result.error;
      const rows = (result.data ?? []).filter(row => (wrongFilter === "全部" || wrongFilter === "未解析" || row.status === wrongFilter) && (wrongFilter !== "未解析" || !row.conciseExplanation) && (!onlyConcise || Boolean(row.conciseExplanation)));
      if (!rows.length) throw new Error(onlyConcise ? "目前沒有含精簡解析的錯題可匯出" : "目前沒有可匯出的錯題");
      const weaknessSummary = await analyzePdfWeakness.mutateAsync({ questionIds: rows.map(row => row.questionId) });
      await downloadWrongQuestionPdf(rows, weaknessSummary);
      toast.success("錯題本 PDF 已開始下載", { description: `已匯出 ${rows.length} 題${onlyConcise ? "含精簡解析的" : ""}${wrongFilter === "未解析" ? "尚未有精簡解析的錯題" : wrongFilter === "全部" ? "錯題" : wrongFilter}紀錄，並加入 AI 弱點分析總結。` });
    } catch (error) {
      toast.error("錯題本 PDF 匯出失敗", { description: error instanceof Error ? error.message : "請稍後再試。" });
    } finally { setIsExportingWrongPdf(false); }
  };
  const exportWrongQuestionCsv = async ({ columnKeys, startDate, endDate, status = wrongFilter, courseType, subcategory }: { columnKeys: WrongQuestionCsvColumnKey[]; startDate?: string; endDate?: string; status?: WrongQuestionCsvStatus; courseType?: string; subcategory?: string }) => {
    if (!user) { startLogin(); return; }
    setIsExportingWrongCsv(true);
    const toastId = toast.loading("正在準備錯題本 CSV", { description: "系統正在整理你目前篩選範圍的個人錯題，請稍候。" });
    try {
      const result = await wrongPdfData.refetch();
      if (result.error) throw result.error;
      const rows = filterWrongQuestionCsvItems(result.data ?? [], { status, startDate, endDate, courseType, subcategory });
      if (!rows.length) throw new Error("目前沒有可匯出的錯題");
      downloadWrongQuestionCsv(rows, columnKeys);
      const estimate = estimateWrongQuestionCsv(rows, columnKeys);
      try { await recordCsvExport.mutateAsync({ status, columnKeys, startDate, endDate, courseType, subcategory, questionCount: estimate.questionCount, estimatedBytes: estimate.estimatedBytes }); } catch (historyError) { console.warn("[CsvExportHistory] failed to record export", historyError); }
      toast.success("錯題本 CSV 已開始下載", { id: toastId, description: `已匯出 ${rows.length} 題${status === "未解析" ? "尚未有精簡解析的錯題" : status === "全部" ? "錯題" : status}紀錄。` });
    } catch (error) {
      toast.error("錯題本 CSV 匯出失敗", { id: toastId, description: error instanceof Error ? error.message : "請稍後再試。" });
    } finally { setIsExportingWrongCsv(false); }
  };
  const startQuiz = () => {
    const pool = [...filtered];
    const selectedQuestions = mode === "practice" && questionOrder === "sequential"
      ? selectSequentialPracticeQuestions(pool, answeredQuestionIds.data ?? [], count).questions
      : pool.sort(() => Math.random() - 0.5).slice(0, Math.min(count, pool.length));
    setMode(mode); setActiveQuestions(selectedQuestions); setCursor(0); setAnswers([]); setSelected(null); setFinished(false); setResult(null); setSection("quiz");
    localStorage.setItem("sep4-active-attempt", JSON.stringify({ mode, count, questionOrder, courseType, subcategory, starTagFilter, excludeTested, questionIds: selectedQuestions.map((q: any) => q.id), answers: [] }));
  };
  const startCoursePractice = (nextCourseType: string) => {
    const coursePool = filterQuestionsByCourse(questions, nextCourseType);
    const selection = selectSmartPracticeQuestions(coursePool, answeredQuestionIds.data ?? [], 5);
    if (!selection.questions.length) return;
    if (selection.usedFallback) toast.info("本課程未測驗題目不足 5 題", { description: `已優先安排 ${selection.untestedCount} 題未測驗題，並以本課程其他題目補足。` });
    if (!selection.untestedCount) toast.info("本課程已完成首輪測驗", { description: "本次將從本課程全部題目重新抽題。" });
    const selectedQuestions = selection.questions;
    setCourseType(nextCourseType); setSubcategory(ALL_SUBCATEGORIES); setMode("practice"); setCount(5); setExcludeTested(true); setActiveQuestions(selectedQuestions); setCursor(0); setAnswers([]); setSelected(null); setFinished(false); setResult(null); setSection("quiz");
    localStorage.setItem("sep4-active-attempt", JSON.stringify({ mode: "practice", count: 5, courseType: nextCourseType, subcategory: ALL_SUBCATEGORIES, starTagFilter, excludeTested: true, questionIds: selectedQuestions.map((q: any) => q.id), answers: [] }));
  };

  const submitAnswer = (option: keyof typeof optionLabels) => {
    if (!current || selected) return;
    setSelected(option);
    const answer: Answer = { questionId: current.id, sequenceNo: cursor, selectedOption: option, correctOption: current.correctOption, isCorrect: option === current.correctOption };
    setAnswers(prev => [...prev, answer]);
  };

  const markAndContinue = (mark?: string) => {
    if (!current || !selected) return;
    const nextAnswers = answers.map(a => a.questionId === current.id ? { ...a, markedReviewError: mark } : a);
    setAnswers(nextAnswers);
    if (cursor + 1 >= activeQuestions.length) {
      if (!user) { setFinished(true); setResult({ score: Math.round(nextAnswers.filter(a => a.isCorrect).length / activeQuestions.length * 100), correctCount: nextAnswers.filter(a => a.isCorrect).length, wrongCount: nextAnswers.filter(a => !a.isCorrect).length, passed80: false }); return; }
      complete.mutate({ mode, questionCount: activeQuestions.length, answers: nextAnswers });
    } else { setCursor(cursor + 1); setSelected(null); localStorage.setItem("sep4-active-attempt", JSON.stringify({ mode, count, courseType, subcategory, starTagFilter, questionIds: activeQuestions.map((q: any) => q.id), answers: nextAnswers })); }
  };

  const nav = (next: Section) => { setSection(next); if (next !== "quiz") { setFinished(false); setActiveQuestions([]); } };

  if (startupStatus === "loading") return <div className="app-shell"><div className="loading-card" role="status" aria-live="polite"><Spinner />正在準備你的題庫…</div></div>;
  if (startupStatus === "recoverable-error") return <div className="app-shell"><div className="loading-card startup-error" role="alert"><CircleAlert size={22} /><strong>題庫目前無法載入</strong><p>{startupTimedOut ? "連線等待時間較長，請檢查網路後重新載入。" : "題庫服務暫時沒有回應，請稍後重試。"}</p><Button className="primary-cta" onClick={() => { setStartupTimedOut(false); void Promise.allSettled([refetchBootstrap(), refresh()]); }}>重新載入</Button></div></div>;

  return <div className={`app-shell reading-scale-${fontScale === 1.15 ? "large" : fontScale === 0.9 ? "small" : "normal"} density-${density}`}>
    <header className="topbar"><div><div className="eyebrow">{SITE_MAIN_TITLE}</div><h1>{SITE_SUBTITLE}</h1></div><div className="top-actions"><Button variant="ghost" className="settings-button" aria-label="閱讀設定" onClick={() => setSection("settings")}><Settings size={17}/><span>閱讀設定</span></Button>{user ? <Button variant="ghost" className="user-pill" onClick={() => logout()}>{user.name || "已登入"} · 登出</Button> : <Button variant="outline" className="login-button" onClick={() => startLogin()}><LogIn size={16}/> Manus OAuth 登入</Button>}</div></header>
    <main className="content">
      {section === "home" && <Dashboard onStart={() => { setSection("quiz"); }} onStartCourse={startCoursePractice} onStartRecentWrong={() => { if (!recentWrongQuestion) return; const full = getWrongQuestionForReplay(questions, recentWrongQuestion.questionId); if (!full) return; setMode("wrong"); setActiveQuestions([full]); setCursor(0); setAnswers([]); setSelected(null); setFinished(false); setSection("quiz"); }} recentWrongQuestion={recentWrongQuestion} onOpenStarred={() => { if (!user) return startLogin(); setSection("starred"); }} data={data} user={user} starStats={starredStats.data} courseProgress={courseProgress.data} learningGoal={learningGoal.data} onAdmin={() => setSection("admin")} />}
      {section === "quiz" && (!activeQuestions.length ? <QuizSetup excludeTested={excludeTested} setExcludeTested={setExcludeTested} canExcludeTested={Boolean(user)} courseType={courseType} setCourseType={setCourseType} courseTypes={sortedCourseTypes} subcategory={subcategory} setSubcategory={setSubcategory} subcategories={subcategories} courseProgress={courseProgress.data} subcategoryProgress={subcategoryProgress.data} courseSort={courseSort} setCourseSort={setCourseSort} learningGoal={learningGoal.data} onUpdateGoal={(targetCompletion: number) => updateLearningGoal.mutate({ targetCompletion })} goalPending={updateLearningGoal.isPending} isLoggedIn={Boolean(user)} mode={mode} setMode={setMode} count={count} setCount={setCount} questionOrder={questionOrder} setQuestionOrder={setQuestionOrder} onStart={startQuiz} available={filtered.length} starredCount={starredIds.size} starTags={starTags} starTagFilter={starTagFilter} setStarTagFilter={setStarTagFilter} /> : <QuizRunner current={current} cursor={cursor} total={activeQuestions.length} selected={selected} mode={mode} finished={finished} result={result} isStarred={starredIds.has(current?.id)} isIssueReported={issueIds.has(current?.id)} starPending={toggleStar.isPending} issuePending={toggleQuestionIssue.isPending} onToggleIssue={() => user ? toggleQuestionIssue.mutate({ questionId: current.id }) : startLogin()} onToggleStar={() => user ? toggleStar.mutate({ questionId: current.id }) : startLogin()} onAnswer={submitAnswer} onMark={markAndContinue} onPrevious={() => { const previousCursor = getPreviousQuestionCursor(cursor); if (previousCursor === cursor) return; const previousQuestion = activeQuestions[previousCursor]; setCursor(previousCursor); setSelected((getSelectedOptionForQuestion(answers, previousQuestion.id) as keyof typeof optionLabels | undefined) ?? null); }} isLoggedIn={Boolean(user)} answerAiExplanation={answerAiExplanationByQuestion[current?.id]} officialConciseExplanation={officialConciseByQuestion[current?.id]} answerAiLoading={answerAiExplanationTarget === current?.id} onExplainAnswer={() => { if (!user) return startLogin(); setAnswerAiExplanationTarget(current.id); explainQuizAnswer.mutate({ questionId: current.id, selectedOption: selected! }); }} onBack={() => { setActiveQuestions([]); setSection("home"); }} />)}
      {section === "wrong" && <WrongPanel rows={wrong.data ?? []} questions={questions} filter={wrongFilter} setFilter={setWrongFilter} exportingPdf={isExportingWrongPdf} exportingCsv={isExportingWrongCsv} onExportPdf={exportWrongQuestionPdf} onExportCsv={exportWrongQuestionCsv} conciseByQuestion={conciseByQuestion} concisePendingCount={concisePendingCount} generatingConcise={generateConciseNotes.isPending} ratingQuestionId={rateConciseNote.isPending ? rateConciseNote.variables?.questionId : null} markingMasteredQuestionId={markWrongMastered.isPending ? markWrongMastered.variables?.questionId : null} onGenerateConcise={() => user ? generateConciseNotes.mutate() : startLogin()} onRateConcise={(questionId: string, feedback: "helpful" | "unclear") => rateConciseNote.mutate({ questionId, feedback })} onMarkMastered={(questionId: string) => markWrongMastered.mutate({ questionId })} aiExplanationByQuestion={aiExplanationByQuestion} aiExplanationTarget={aiExplanationTarget} onExplain={(questionId: string) => { setAiExplanationTarget(questionId); explainWrongQuestion.mutate({ questionId }); }} onStart={(q: any) => { const full = getWrongQuestionForReplay(questions, q.questionId); if (!full) return; setMode("wrong"); setActiveQuestions([full]); setCursor(0); setAnswers([]); setSelected(null); setFinished(false); setSection("quiz"); }} />}
      {section === "starred" && <StarredPanel starRows={starred.data ?? []} questions={questions} onStartRandom={() => { if (!user) return startLogin(); setMode("starred"); setActiveQuestions([]); setSection("quiz"); }} onStart={(questionId: string) => { const full = getWrongQuestionForReplay(questions, questionId); if (!full) return; setMode("starred"); setActiveQuestions([full]); setCursor(0); setAnswers([]); setSelected(null); setFinished(false); setSection("quiz"); }} onSaveTag={(questionId: string, tag: string | null) => updateStarTag.mutate({ questionId, tag })} onSaveReminder={(questionId: string, reminderDate: string | null) => updateStarReminder.mutate({ questionId, reminderDate })} />}
      {section === "issues" && <QuestionIssuesPanel rows={questionIssues.data ?? []} questions={questions} onUpdate={(input: any) => questionIssues.refetch()} />}
      {section === "stats" && <StatsPanel attempts={history.data ?? []} stats={stats.data} starredStats={starredStats.data} wrongProgress={wrongProgress} />}
      {section === "admin" && <><AdminReviewStateNotice isAdmin={user?.role === "admin"} /><AdminPanel isAdmin={user?.role === "admin"} /></>}
      {section === "settings" && <ReadingSettings fontScale={fontScale} setFontScale={setFontScale} density={density} setDensity={setDensity} onBack={() => setSection("home")} />}
    </main>
    <nav className="bottom-nav" aria-label="主要導覽">{[["home", HomeIcon, "首頁"],["quiz", BookOpenCheck, "測驗"],["wrong", RotateCcw, "錯題"],["starred", Star, "星號"],["issues", Flag, "問題"],["stats", History, "統計"]].map(([key, Icon, label]) => <button key={key as string} className={section === key ? "active" : ""} aria-current={section === key ? "page" : undefined} aria-label={`${label as string}${section === key ? "，目前頁面" : ""}`} onClick={() => nav(key as Section)}><Icon size={19}/><span>{label as string}</span>{section === key && <span className="sr-only">目前頁面</span>}</button>)}</nav>
  </div>;
}

function Dashboard({ onStart, onStartCourse, onStartRecentWrong, recentWrongQuestion, onOpenStarred, data, user, starStats, courseProgress, learningGoal, onAdmin }: any) { const reminderText = !user ? "登入後建立個人星號複習" : starStats?.dueCount ? `有 ${starStats.dueCount} 題已到提醒日` : starStats?.upcomingCount ? `7 日內有 ${starStats?.upcomingCount} 題待複習` : "目前沒有到期提醒"; const recentDate = recentWrongQuestion?.updatedAt ? new Date(recentWrongQuestion.updatedAt).toLocaleDateString("zh-TW", { month: "numeric", day: "numeric" }) : null; return <div className="dashboard-grid"><section className="hero-card"><div className="hero-copy"><Badge className="soft-badge"><Target size={14}/> {SITE_SUBTITLE}</Badge><h2>{SITE_MAIN_TITLE}</h2><p className="hero-subtitle">以官方題庫為核心，練習每一道 9/4 筆試題。</p><Button className="primary-cta" onClick={onStart}>開始測驗 <ArrowRight size={17}/></Button></div><div className="hero-orbit"><span>80</span><small>目標分</small></div></section><section className="metric-row"><Metric icon={<Flame/>} label="目前錯題" value={user ? "同步後查看" : "登入後同步"}/><Metric icon={<CheckCircle2/>} label="已熟悉" value="—"/><Metric icon={<ShieldCheck/>} label="題庫狀態" value={`${data?.qa?.enabled ?? 0} 題可練`}/></section>{user && recentWrongQuestion && <section className="recent-wrong-row" aria-label="近期錯題"><div><div className="eyebrow">近期錯題</div><strong>{recentWrongQuestion.questionId}</strong><span>錯誤 {recentWrongQuestion.wrongCount} 次{recentDate ? ` · 最近作答 ${recentDate}` : ""}</span></div><Button variant="outline" onClick={onStartRecentWrong}><RotateCcw size={16}/> 續練這題</Button></section>}<HomeCourseSummary user={user} courseProgress={courseProgress} learningGoal={learningGoal} onStartCourse={onStartCourse}/><section className="home-star-summary"><div><div className="eyebrow">星號複習</div><strong>{starStats?.completionRate ?? 0}% 已複習</strong><p>{starStats?.reviewedCount ?? 0} / {starStats?.total ?? 0} 題 · {reminderText}</p></div><Button variant="outline" onClick={onOpenStarred}><Star size={16}/> 前往星號複習</Button></section><section className="quick-grid"><QuickCard title="快速練習" desc="5 題即時回饋" onClick={onStart}/><QuickCard title="20 題模擬考" desc="完成後揭曉分數" onClick={onStart}/><QuickCard title="考前衝刺" desc="優先複習弱點" onClick={onStart}/></section>{user?.role === "admin" && <button className="admin-link" onClick={onAdmin}><ShieldCheck size={16}/> 開啟題庫管理後台</button>}</div> }
function getPracticeStatus(lastAnsweredAt: Date | string | null) { if (!lastAnsweredAt) return { label: "尚未作答", dateLabel: "最近作答 —", stale: true }; const date = new Date(lastAnsweredAt); const days = Math.floor((Date.now() - date.getTime()) / 86400000); const label = days <= 0 ? "今天已練習" : days === 1 ? "昨天練習" : `${days} 天前練習`; return { label, dateLabel: `最近作答 ${date.toLocaleDateString("zh-TW", { month: "numeric", day: "numeric" })}`, stale: days >= 7 }; }
function HomeCourseSummary({ user, courseProgress, learningGoal, onStartCourse }: any) { if (!user) return <section className="home-course-summary home-course-summary-guest"><div><div className="eyebrow">課程學習摘要</div><strong>登入後掌握各科進度</strong><p>答對率、完成度與目標提醒會依你的作答紀錄同步。</p></div><Button variant="outline" onClick={() => startLogin()}><LogIn size={16}/> 登入查看</Button></section>; if (!courseProgress) return <section className="home-course-summary"><span className="muted">正在載入你的課程學習摘要…</span></section>; const target = learningGoal?.targetCompletion ?? 60; const weakest = getWeakestCourse(courseProgress); const totalAvailable = courseProgress.reduce((sum: number, course: any) => sum + course.available, 0); const totalAnsweredQuestions = courseProgress.reduce((sum: number, course: any) => sum + course.answeredQuestions, 0); return <section className="home-course-summary"><div className="home-course-heading"><div><div className="eyebrow">課程學習摘要</div><strong>掌握每一科的下一步</strong></div><Badge className="course-goal-badge">目標 {target}%</Badge></div><section className="answer-progress-summary" aria-label="答題進度摘要"><div className="answer-progress-summary-heading"><div><div className="eyebrow">答題進度</div><strong>掌握整體與各科完成狀況</strong></div><Badge variant="outline">{totalAnsweredQuestions} / {totalAvailable} 題</Badge></div><div className="answer-progress-row answer-progress-total"><span>總題數</span><strong>{totalAvailable}</strong><span>已答題數</span><strong>{totalAnsweredQuestions}</strong></div>{courseProgress.map((course: any) => <div className="answer-progress-row" key={`answer-progress-${course.source}`}><span>{course.label}</span><strong>總題數：{course.available}</strong><strong>已答題數：{course.answeredQuestions}</strong></div>)}</section>{weakest ? <div className="weak-course-action"><div><div className="weak-course-kicker"><Flame size={15}/> 今日優先加強</div><strong>{weakest.label}</strong><p>目前答對率 {weakest.accuracy}% · 直接開始 5 題練習。</p></div><Button className="primary-cta" onClick={() => onStartCourse(weakest.source)}>一鍵練習最弱科目 <ArrowRight size={16}/></Button></div> : <div className="weak-course-empty"><Sparkles size={17}/><span>完成第一回練習後，系統會為你找出最需要加強的科目。</span></div>}<div className="home-course-grid">{courseProgress.map((course: any) => { const remaining = Math.max(target - course.completion, 0); const practiceStatus = getPracticeStatus(course.lastAnsweredAt); return <article className="home-course-row" key={course.source}><div className="home-course-row-heading"><strong>{course.label}</strong><span>{course.accuracy === null ? "尚未作答" : `答對率 ${course.accuracy}%`}</span></div><div className="home-course-meta"><span>{practiceStatus.dateLabel} · </span><span className={practiceStatus.stale ? "stale-practice" : ""}>{practiceStatus.label}</span></div><div className="home-course-track"><i style={{ width: `${course.completion}%` }}/></div><div className="home-course-row-footer"><span>{course.completion}% 完成 {remaining ? `· 距目標 ${remaining}%` : "· 已達目標"}</span><Button variant="outline" size="sm" onClick={() => onStartCourse(course.source)}>練這科 <ArrowRight size={14}/></Button></div></article>; })}</div></section>; }
function Metric({ icon, label, value }: any) { return <Card className="metric-card"><CardContent><div className="metric-icon">{icon}</div><div><span>{label}</span><strong>{value}</strong></div></CardContent></Card> }
function QuickCard({ title, desc, onClick }: any) { return <button className="quick-card" onClick={onClick}><span>{title}</span><small>{desc}</small><ArrowRight size={16}/></button> }
function CourseProgressHint({ courseType, courseTypes, courseProgress, subcategory, subcategories, subcategoryProgress, learningGoal, onUpdateGoal, goalPending, isLoggedIn }: any) {
  const safeCourseTypes = courseTypes ?? [];
  const safeSubcategories = subcategories ?? [];
  const showingSubcategory = subcategory !== ALL_SUBCATEGORIES;
  const visibleTypes = showingSubcategory ? safeSubcategories.filter((type: any) => type.id === subcategory) : courseType === ALL_COURSE_TYPES ? safeCourseTypes : safeCourseTypes.filter((type: any) => type.id === courseType);
  const progressRows = showingSubcategory ? subcategoryProgress : courseProgress;
  const weakScopeIds = showingSubcategory ? [subcategory] : safeSubcategories.filter((type: any) => type.status !== "needs_manual_review").map((type: any) => type.id);
  const weakestSubcategory = getWeakestSubcategory(subcategoryProgress, weakScopeIds);
  if (!isLoggedIn) return <div className="course-progress-hint muted"><strong>登入後查看個人課程進度</strong><span>系統會記錄各課程的答對率與完成度。</span></div>;
  if (!progressRows) return <div className="course-progress-hint muted">正在載入你的課程進度…</div>;
  const target = learningGoal?.targetCompletion ?? 60;
  const averageCompletion = visibleTypes.length ? Math.round(visibleTypes.reduce((sum: number, type: any) => sum + (progressRows.find((item: any) => item.source === type.id)?.completion ?? 0), 0) / visibleTypes.length) : 0;
  const remaining = Math.max(target - averageCompletion, 0);
  return <section className="course-progress-hint" aria-label="課程進度">
    <div className="course-progress-heading"><strong>{showingSubcategory ? "次分類進度" : "課程進度"}</strong><span>完成度以已作答的不重複題目計算</span></div>
    {weakestSubcategory ? <div className="course-goal-reminder needs-action"><Flame size={16}/><span>本範圍優先加強：{weakestSubcategory.label ?? weakestSubcategory.source}（答對率 {weakestSubcategory.accuracy}%）。</span></div> : <div className="course-goal-reminder on-track"><Sparkles size={16}/><span>完成第一回合後，系統會顯示此範圍最需要加強的次分類。</span></div>}
    <div className={`course-goal-reminder ${remaining ? "needs-action" : "on-track"}`}><Sparkles size={16}/><span>{remaining ? `距離 ${target}% 完成度目標還有 ${remaining}%，完成下一回合就更接近。` : `已達成 ${target}% 完成度目標，保持這個節奏。`}</span></div>
    <label className="goal-picker">設定目標完成度<select aria-label="設定目標完成度" value={target} disabled={goalPending} onChange={event => onUpdateGoal(Number(event.target.value))}>{[25, 40, 60, 80, 100].map(value => <option value={value} key={value}>{value}%</option>)}</select></label>
    <div className="course-progress-list">{visibleTypes.map((type: any) => {
      const progress = progressRows.find((item: any) => item.source === type.id);
      const completion = progress?.completion ?? 0;
      const accuracy = progress?.accuracy;
      return <div className="course-progress-row" key={type.id}>
        <div className="course-progress-copy"><strong>{type.label}</strong><span>{progress ? `${progress.answered} 次作答 · ${completion}% 完成` : "尚未開始"}</span></div>
        <div className="course-progress-track" aria-label={`${type.label} 完成度 ${completion}%`}><i style={{ width: `${completion}%` }}/></div>
        <span className="course-accuracy">{accuracy === null || accuracy === undefined ? "尚未作答" : `答對率 ${accuracy}%`}</span>
      </div>;
    })}</div>
  </section>;
}
function QuizSetup({ excludeTested, setExcludeTested, canExcludeTested, courseType, setCourseType, courseTypes, subcategory, setSubcategory, subcategories, courseProgress, subcategoryProgress, courseSort, setCourseSort, learningGoal, onUpdateGoal, goalPending, isLoggedIn, mode, setMode, count, setCount, questionOrder, setQuestionOrder, onStart, available, starredCount, starTags, starTagFilter, setStarTagFilter }: any) { const starredMode = mode === "starred"; const practiceMode = mode === "practice"; return <div className="setup-wrap"><button className="back-link" onClick={() => window.history.back()}><ChevronLeft size={16}/> 回首頁</button><div className="section-heading"><div className="eyebrow">測驗設定</div><h2>今天想怎麼練？</h2><p>選擇課程類型、次分類、題數與範圍，系統會避免同場重複題目。</p></div><Card className="setup-card"><CardHeader><CardTitle>測驗模式</CardTitle></CardHeader><CardContent><Tabs value={mode} onValueChange={v => setMode(v as Mode)}><TabsList className="mode-tabs mode-tabs-four"><TabsTrigger value="practice">練習模式</TabsTrigger><TabsTrigger value="mock">模擬考</TabsTrigger><TabsTrigger value="wrong">錯題重刷</TabsTrigger><TabsTrigger value="starred">星號隨機</TabsTrigger></TabsList><TabsContent value="practice"><p className="muted">每題作答後立即顯示正解與解析。</p></TabsContent><TabsContent value="mock"><p className="muted">20 題完成前不公布單題對錯，完成後顯示是否達標。</p></TabsContent><TabsContent value="wrong"><p className="muted">集中處理待複習題目，連續答對兩次即標為已熟悉。</p></TabsContent><TabsContent value="starred"><p className="muted">僅從你標記星號的題目隨機抽題，也可以進一步選擇指定標籤、課程類型與次分類。</p></TabsContent></Tabs><label>課程排序<select aria-label="課程排序" value={courseSort} onChange={event => setCourseSort(event.target.value as CourseSort)}><option value="default">預設排序</option><option value="accuracy-asc">答對率最低優先</option><option value="completion-asc">完成度最低優先</option></select></label><label>課程類型<select aria-label="課程類型" value={courseType} onChange={e => setCourseType(e.target.value)}><option value={ALL_COURSE_TYPES}>全部課程</option>{courseTypes.map((type: { id: string; label: string }) => <option key={type.id} value={type.id}>{type.label}</option>)}</select></label><label>次分類<select aria-label="次分類" value={subcategory} onChange={e => setSubcategory(e.target.value)}><option value={ALL_SUBCATEGORIES}>全部次分類</option>{subcategories.map((type: { id: string; label: string; status: string }) => <option key={type.id} value={type.id}>{type.status === "needs_manual_review" ? `${type.label}（待確認）` : type.label}</option>)}</select></label><CourseProgressHint courseType={courseType} courseTypes={courseTypes} courseProgress={courseProgress} subcategory={subcategory} subcategories={subcategories} subcategoryProgress={subcategoryProgress} learningGoal={learningGoal} onUpdateGoal={onUpdateGoal} goalPending={goalPending} isLoggedIn={isLoggedIn}/>{practiceMode && <label className="exclude-tested-option"><span><input type="checkbox" checked={excludeTested} disabled={!canExcludeTested} onChange={event => setExcludeTested(event.target.checked)} /> 排除已測驗過題目</span><small>{canExcludeTested ? "只套用一般練習；模擬考、星號與錯題重刷仍可重複測驗。" : "登入後才能依你的個人作答紀錄排除題目。"}</small></label>}{practiceMode && <label>出題順序<select aria-label="出題順序" value={questionOrder} onChange={e => setQuestionOrder(e.target.value as QuestionOrder)}><option value="sequential">依題號順序（接續未刷）</option><option value="random">隨機出題</option></select><small>依目前課程與次分類範圍，從最前面的未刷題號開始。</small></label>}<label>題數<select value={count} onChange={e => setCount(Number(e.target.value))}><option value={5}>5 題快速練習</option><option value={10}>10 題一般練習</option><option value={20}>20 題模擬考</option></select></label>{starredMode && <label>星號標籤<select value={starTagFilter} onChange={e => setStarTagFilter(e.target.value)}><option>全部</option>{starTags.map((tag: string) => <option key={tag}>{tag}</option>)}</select></label>}<Button className="primary-cta wide" onClick={onStart} disabled={!available}>開始這一回合 <ArrowRight size={17}/></Button><p className="availability">{starredMode ? `目前有 ${available} / ${starredCount} 題星號題目符合篩選` : practiceMode && excludeTested ? `排除已測驗題目後，目前有 ${available} 題可用` : `目前課程與次分類範圍有 ${available} 題可用`}</p></CardContent></Card></div> }
function QuizRunner({ current, cursor, total, selected, mode, finished, result, isStarred, isIssueReported, starPending, issuePending, onToggleIssue, onToggleStar, onAnswer, onMark, onPrevious, onBack, isLoggedIn, answerAiExplanation, officialConciseExplanation, answerAiLoading, onExplainAnswer }: any) {
  const [showExplanation, setShowExplanation] = useState(false);
  useEffect(() => { setShowExplanation(false); }, [current?.id]);
  const mock = mode === "mock";
  const isLastQuestion = cursor + 1 === total;
  const canMoveNext = Boolean(selected && (selected === current.correctOption || mock));
  const questionText = current?.text?.trim() || "題幹正在同步，請稍候後重新開始本回合。";
  return <div className="runner-wrap"><button className="back-link" onClick={onBack}><ChevronLeft size={16}/> 結束本回合</button>{finished ? <Card className="result-card"><div className="result-kicker">本回合完成</div><h2>{result?.score ?? 0}<small> 分</small></h2><p>{result?.passed80 ? "已達到 80 分目標。" : "還差一點，下一回合會更穩。"}</p><div className="result-stats"><span>答對 <b>{result?.correctCount ?? 0}</b></span><span>答錯 <b>{result?.wrongCount ?? 0}</b></span></div><Button className="primary-cta" onClick={onBack}>返回首頁</Button></Card> : <><div className="progress-line"><span>第 {cursor + 1} / {total} 題</span><div><i style={{ width: `${((cursor + 1) / total) * 100}%` }}/></div></div><Card className="question-card"><div className="question-meta"><div className="question-badges"><Badge variant="outline">{current.source === "AI" ? "AI 工具應用" : "電腦硬體"}</Badge>{current.needsReview && <Badge className="review-badge"><CircleAlert size={13}/> 待審</Badge>}</div><Button variant={isStarred ? "default" : "outline"} size="sm" className={`star-button ${isStarred ? "starred" : ""}`} aria-pressed={isStarred} disabled={starPending} onClick={onToggleStar}><Star size={16} fill={isStarred ? "currentColor" : "none"}/>{isStarred ? "已標記" : "標記星號"}</Button><Button variant={isIssueReported ? "default" : "outline"} size="sm" className={`issue-button ${isIssueReported ? "reported" : ""}`} aria-pressed={isIssueReported} disabled={issuePending} onClick={onToggleIssue}><Flag size={16}/>{isIssueReported ? "已標記問題" : "標記問題"}</Button></div><h2>{questionText}</h2>{current.mediaUrl && current.requiresMedia && <figure className="question-media"><img src={current.mediaUrl} alt={`官方題圖：${current.id}`} loading="lazy" /></figure>}<div className="answers">{Object.entries(current.options).map(([key, value]) => <button key={key} className={`answer-button ${selected ? (key === current.correctOption ? "correct" : key === selected ? "wrong" : "muted") : ""}`} onClick={() => onAnswer(key as any)}><span className="answer-letter">{key}</span><span>{value as string}</span>{selected && key === current.correctOption && <CheckCircle2 size={18}/>} {selected && key === selected && key !== current.correctOption && <XCircle size={18}/>}</button>)}</div>{!mock && <div className="quiz-explanation-toggle">{selected && <div className={`feedback ${selected === current.correctOption ? "good" : "bad"}`}><strong>{selected === current.correctOption ? "答對了" : "再看一次"}</strong><p>你的答案：{selected}</p></div>}{!showExplanation && <Button variant="outline" size="sm" onClick={() => setShowExplanation(true)}><BrainCircuit size={16}/>查看解析</Button>}{showExplanation && <OfficialV2Explanation correctOption={current.correctOption} explanation={current.explanation} compact />}</div>}{selected && mock && <div className="mock-hint">答案已暫存，完成整份模擬考後揭曉。</div>}{selected && !mock && selected !== current.correctOption && <div className="mark-actions"><span>這題答錯的原因？</span><Button variant="outline" onClick={() => onMark("真的不會")}>真的不會</Button><Button variant="outline" onClick={() => onMark("題目看反")}>題目看反</Button></div>}<div className="question-navigation"><Button variant="outline" disabled={cursor === 0} onClick={onPrevious}><ChevronLeft size={17}/>上一題</Button>{canMoveNext && <Button className="primary-cta" onClick={() => onMark()}>{isLastQuestion ? "查看結果" : "下一題"}<ArrowRight size={17}/></Button>}</div></Card></>}</div>
}
function QuestionIssuesPanel({ rows, questions, onUpdate }: any) {
  const update = trpc.questionIssues.update.useMutation({ onSuccess: () => { onUpdate?.(); toast.success("問題回報已更新"); }, onError: () => toast.error("問題回報更新未完成", { description: "請稍後再試，官方題庫內容未變更。" }) });
  if (!rows.length) return <div className="panel-wrap"><div className="section-heading"><h2>題目問題</h2></div><div className="empty-state"><Flag size={28}/><h3>尚未標記有問題的題目</h3><p>答題時遇到 OCR、題幹、選項或答案疑似有誤，可按下「標記問題」放到這裡，之後再對照官方 PDF。</p></div></div>;
  return <div className="panel-wrap question-issues-panel"><div className="section-heading"><h2>題目問題</h2></div><p className="muted">這裡獨立保存你標記的題目；「待核對」不代表官方資料已被修改。</p><div className="question-issues-list">{rows.map((row: any) => { const question = questions.find((item: any) => item.id === row.questionId); return <Card className="question-issue-row" key={row.id}><CardContent><div className="question-issue-copy"><div className="question-issue-title"><Badge className="issue-badge"><Flag size={13}/> {row.reviewStatus}</Badge><strong>{row.questionId}</strong></div><p>{question?.text?.slice(0, 180) || "題目內容暫時無法顯示。"}</p><label>問題類型<select value={row.issueType} onChange={event => update.mutate({ questionId: row.questionId, issueType: event.target.value })}><option>OCR 辨識疑似錯誤</option><option>題幹疑似有誤</option><option>選項疑似有誤</option><option>答案疑似有誤</option><option>其他問題</option></select></label><label>對照備註<textarea defaultValue={row.note ?? ""} maxLength={1000} rows={3} placeholder="例如：請回看官方 PDF 第 12 頁" onBlur={event => { const note = event.target.value.trim(); if (note !== (row.note ?? "")) update.mutate({ questionId: row.questionId, note: note || null }); }}/></label><label>PDF 對照狀態<select value={row.reviewStatus} onChange={event => update.mutate({ questionId: row.questionId, reviewStatus: event.target.value as "待核對" | "已確認問題" | "非問題" | "已修正" })}><option>待核對</option><option>已確認問題</option><option>非問題</option><option>已修正</option></select></label></div></CardContent></Card>; })}</div></div>;
}

  export function StarMetaEditor({ row, onSaveTag, onSaveReminder }: any) { const [tag, setTag] = useState(row.tag || ""); const [reminderDate, setReminderDate] = useState(row.reminderDate || ""); useEffect(() => { setTag(row.tag || ""); setReminderDate(row.reminderDate || ""); }, [row.tag, row.reminderDate]); return <div className="star-meta-editor"><div className="tag-editor"><input aria-label={`標籤 ${row.questionId}`} value={tag} maxLength={64} placeholder="例如：考前必看" onChange={event => setTag(event.target.value)} /><Button variant="outline" size="sm" onClick={() => onSaveTag(row.questionId, tag.trim() || null)}>儲存標籤</Button></div><div className="reminder-editor"><label>提醒日期<input aria-label={`提醒日期 ${row.questionId}`} type="date" value={reminderDate} onChange={event => setReminderDate(event.target.value)} /></label><Button variant="outline" size="sm" onClick={() => onSaveReminder(row.questionId, reminderDate || null)}>儲存提醒</Button></div></div> }
function StarredPanel({ starRows, questions, onStartRandom, onStart, onSaveTag, onSaveReminder }: any) {
  const today = new Date().toISOString().slice(0, 10);
  const starred = starRows.map((row: any) => ({ ...row, question: getWrongQuestionForReplay(questions, row.questionId) })).filter((row: any) => row.question);
  return <div className="panel-wrap starred-panel"><div className="section-heading"><h2>星號複習</h2></div><section className="starred-section"><div className="starred-heading"><div><Star size={17} fill="currentColor"/><strong>我的星號題目</strong></div><Badge>{starred.length} 題</Badge></div><p className="starred-page-intro">星號題目獨立於錯題本；可作為考前重點、容易混淆或尚未熟悉題目的個人清單。</p>{starred.length ? <><div className="starred-page-actions"><Button className="primary-cta" onClick={onStartRandom}><Shuffle size={16}/>星號隨機測驗</Button><span>將從目前 {starred.length} 題星號題中出題。</span></div><div className="starred-list">{starred.map((row: any) => <Card className="starred-row" key={row.id}><CardContent><div><h3>{row.question.questionId}</h3><p>{row.question.text.slice(0, 110)}{row.question.text.length > 110 ? "…" : ""}</p>{row.reminderDate && <Badge className={row.reminderDate <= today ? "reminder-badge due" : "reminder-badge"}>{row.reminderDate <= today ? "今日／已到期" : `提醒 ${row.reminderDate}`}</Badge>}<StarMetaEditor row={row} onSaveTag={onSaveTag} onSaveReminder={onSaveReminder}/></div><Button variant="outline" onClick={() => onStart(row.questionId)}><RotateCcw size={16}/>重刷</Button></CardContent></Card>)}</div></> : <div className="empty-state"><Star size={28}/><h3>尚未有星號題目</h3><p>在答題時按下「標記星號」，就能將題目加入這個獨立複習清單。</p></div>}</section></div>;
}
function ConciseWrongQuestionNote({ note, loading, onRate }: any) {
  const [expanded, setExpanded] = useState(true);
  const generatedLabel = note.generatedAt ? new Date(note.generatedAt).toLocaleString("zh-TW", { year: "numeric", month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" }) : "尚無時間紀錄";
  const contentId = `concise-note-${note.questionId}`;
  return <section className={`concise-note-card ${expanded ? "is-expanded" : "is-collapsed"}`} aria-label="精簡記憶解析"><div className="concise-note-heading"><div className="concise-note-title"><BrainCircuit size={16}/><strong>精簡記憶解析</strong><Badge variant="outline">第 {note.generationCount ?? 1} 版</Badge></div><Button variant="ghost" size="sm" className="concise-collapse-button" aria-expanded={expanded} aria-controls={contentId} onClick={() => setExpanded(current => !current)}>{expanded ? "收合" : "展開"}<ChevronDown size={15}/></Button></div><div id={contentId} className="concise-note-content" hidden={!expanded}><p><b>判斷重點：</b>{note.summary}</p><p><b>記憶口訣：</b>{note.memoryTip}</p><small>最近產生：{generatedLabel}。內容僅依官方題庫、答案與解析產生，不會改動官方資料。</small><div className="concise-feedback"><span>{note.feedback === "helpful" ? "已標記有幫助" : note.feedback === "unclear" ? "已標記不夠清楚，可由上方批次再生" : "這份解析有幫助嗎？"}</span><div className="concise-feedback-actions"><Button variant="outline" size="icon" className={`concise-feedback-icon ${note.feedback === "helpful" ? "is-selected" : ""}`} aria-label="這份解析有幫助" aria-pressed={note.feedback === "helpful"} disabled={loading} onClick={() => onRate("helpful")}><ThumbsUp size={16}/></Button><Button variant="outline" size="icon" className={`concise-feedback-icon ${note.feedback === "unclear" ? "is-selected" : ""}`} aria-label={loading ? "正在重新產生解析" : "這份解析不夠清楚"} aria-pressed={note.feedback === "unclear"} disabled={loading} onClick={() => onRate("unclear")}><RefreshCw size={16} className={loading ? "animate-spin" : undefined}/></Button></div></div></div></section>
}
function WrongQuestionTextPreview({ questionId, questionText, options, correctOption, selectedOption }: { questionId: string; questionText?: string; options?: unknown; correctOption?: string; selectedOption?: string | null }) { const [expanded, setExpanded] = useState(false); const contentId = `wrong-question-text-${questionId}`; const officialText = questionText?.trim() || "官方題幹暫時無法顯示。"; const officialOptions = getOfficialOptionPreview(options, correctOption, selectedOption); return <section className={`wrong-question-summary ${expanded ? "is-expanded" : ""}`}><button type="button" aria-expanded={expanded} aria-controls={contentId} onClick={() => setExpanded(current => !current)}><span><b>{expanded ? "完整官方題幹" : "題幹摘要"}</b><span>{expanded ? officialText : getQuestionTextSummary(officialText)}</span></span><ChevronDown size={17}/></button>{expanded && <div id={contentId} className="official-options-preview"><div className="official-options-heading"><strong>官方選項快速預覽</strong>{correctOption && <Badge className="official-correct-badge">官方正解：{correctOption}</Badge>}</div>{selectedOption && <div className="option-comparison-legend" aria-label="選項對照說明"><span className="is-selected">你的作答</span><span className="is-correct">官方正解</span></div>}{officialOptions.length ? <ul>{officialOptions.map(option => <li key={option.label} className={`${option.isCorrect ? "is-correct" : ""} ${option.isSelected ? "is-selected" : ""}`.trim()} aria-label={`${option.label}：${option.text}${option.isSelected ? "，你的作答" : ""}${option.isCorrect ? "，官方正解" : ""}`}><b>{option.label}</b><span>{option.text}</span><div className="option-comparison-labels">{option.isSelected && <small className="is-selected">你的作答</small>}{option.isCorrect && <small className="is-correct">官方正解</small>}</div></li>)}</ul> : <p>官方選項暫時無法顯示。</p>}</div>}</section>; }
function WrongPanel({ rows, questions, filter, setFilter, exportingPdf, exportingCsv, onExportPdf, onExportCsv, conciseByQuestion, concisePendingCount, generatingConcise, ratingQuestionId, markingMasteredQuestionId, onGenerateConcise, onRateConcise, onMarkMastered, aiExplanationByQuestion, aiExplanationTarget, onExplain, onStart }: any) {
  const utils = trpc.useUtils();
  const unclearConciseCount = Object.values(conciseByQuestion).filter((note: any) => note.feedback === "unclear").length;
  const [batchExpanded, setBatchExpanded] = useState(true);
  const regenerateUnclear = trpc.wrongQuestions.regenerateUnclearConciseBatch.useMutation({ onSuccess: async value => { await utils.wrongQuestions.conciseList.invalidate(); toast.success("不夠清楚題目已重新產生", { description: `已更新 ${value.regeneratedCount} 題${value.failedCount ? `，${value.failedCount} 題暫時失敗` : ""}；尚有 ${value.remainingUnclearCount} 題可再處理。` }); }, onError: () => toast.error("批次重新產生未完成", { description: "請稍後再試；原本已儲存的解析仍保留。" }) });
  const visible = filter === "未解析" ? filterWrongQuestionsMissingConcise(rows, new Set(Object.keys(conciseByQuestion))) : filterWrongQuestions(rows, filter);
  return <div className="panel-wrap wrong-panel">
    <div className="section-heading"><h2>錯題本</h2></div>
    
    <div className="wrong-book-toolbar"><div className="filter-pills">{["待複習", "已熟悉", "全部"].map(f => <button className={filter === f ? "selected" : ""} onClick={() => setFilter(f)} key={f}>{f}</button>)}</div><div className="pdf-export-actions"><Button variant="outline" size="sm" disabled={!visible.length || exportingPdf} onClick={() => onExportPdf(false)}><Download size={15}/>{exportingPdf ? "正在建立 PDF…" : `匯出${filter === "全部" ? "錯題本" : filter} PDF`}</Button><CsvExportAdvancedControls rows={rows} filter={filter} exporting={exportingCsv} onExport={onExportCsv}/></div></div>
    {visible.length ? visible.map((r: any) => { const ai = aiExplanationByQuestion[r.questionId]; const loading = aiExplanationTarget === r.questionId; const concise = conciseByQuestion[r.questionId]; const rating = ratingQuestionId === r.questionId; const question = getWrongQuestionForReplay(questions, r.questionId); const officialV2 = getOfficialV2Explanation((question as any) ?? {}); const markingMastered = markingMasteredQuestionId === r.questionId; return <Card className="wrong-row" key={r.id}><CardContent><div className="wrong-card-content"><Badge>{r.status}</Badge><h3>{r.questionId}</h3><p>錯誤 {r.wrongCount} 次 · 連續答對 {r.consecutiveCorrect} 次</p><WrongQuestionTextPreview questionId={r.questionId} questionText={(question as any)?.text} options={(question as any)?.options} correctOption={(question as any)?.correctOption} selectedOption={r.lastSelectedOption}/><OfficialV2Explanation correctOption={officialV2.officialAnswer} explanation={officialV2.v2Explanation} /></div><div className="wrong-card-actions" aria-label={`${r.questionId} 操作`}><Button variant="outline" onClick={() => onStart({ questionId: r.questionId })}><RotateCcw size={16}/>重刷</Button><Button variant="outline" disabled={r.status === "已熟悉" || markingMastered} onClick={() => onMarkMastered(r.questionId)}><CheckCircle2 size={16}/>{markingMastered ? "標記中…" : r.status === "已熟悉" ? "已熟悉" : "標記已熟悉"}</Button></div></CardContent></Card>; }) : <div className="empty-state"><RotateCcw size={28}/><h3>目前沒有符合條件的錯題</h3><p>完成幾回練習後，這裡會自動整理你的複習清單。</p></div>}
  </div>;
}
function CsvExportControls({ rows, filter, exporting, onExport }: { rows: any[]; filter: WrongQuestionCsvStatus; exporting: boolean; onExport: (options: { columnKeys: WrongQuestionCsvColumnKey[]; startDate?: string; endDate?: string; status?: WrongQuestionCsvStatus; courseType?: string; subcategory?: string }) => void }) {
  const { user } = useAuth();
  const exportData = trpc.wrongQuestions.exportPdfData.useQuery(undefined, { enabled: Boolean(user) });
  const [columnKeys, setColumnKeys] = useState<WrongQuestionCsvColumnKey[]>(getDefaultWrongQuestionCsvColumns());
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [courseType, setCourseType] = useState("");
  const [subcategory, setSubcategory] = useState("");
  const [previewCount, setPreviewCount] = useState<number | null>(null);
  const [presetName, setPresetName] = useState("");
  const [presets, setPresets] = useState<WrongQuestionCsvPreset[]>([]);
  const [selectedPresetId, setSelectedPresetId] = useState("");
  const [renamePresetName, setRenamePresetName] = useState("");
  const storageKey = `sep4-wrong-question-csv-presets-${user?.id ?? "guest"}`;
  const exportRows = exportData.data ?? [];
  const courseTypes = useMemo(() => Array.from(new Map(exportRows.filter(row => row.courseType).map(row => [row.courseType!, row.courseLabel || row.courseType!])).entries()).map(([id, label]) => ({ id, label })).sort((left, right) => left.label.localeCompare(right.label, "zh-TW")), [exportRows]);
  const subcategories = useMemo(() => Array.from(new Set(exportRows.filter(row => !courseType || row.courseType === courseType).map(row => row.subcategory || "待確認"))).sort((left, right) => left.localeCompare(right, "zh-TW")), [exportRows, courseType]);
  const hasPending = rows.some(row => row.status === "待複習");
  const toggleColumn = (key: WrongQuestionCsvColumnKey) => setColumnKeys(current => current.includes(key) ? current.filter(item => item !== key) : [...current, key]);
  const filterOptions = (status: WrongQuestionCsvStatus) => ({ columnKeys, startDate: startDate || undefined, endDate: endDate || undefined, courseType: courseType || undefined, subcategory: subcategory || undefined, status });
  const persistPresets = (next: WrongQuestionCsvPreset[]) => { setPresets(next); localStorage.setItem(storageKey, serializeWrongQuestionCsvPresets(next)); };
  useEffect(() => { setPresets(readWrongQuestionCsvPresets(localStorage.getItem(storageKey))); setSelectedPresetId(""); setRenamePresetName(""); }, [storageKey]);
  useEffect(() => { if (subcategory && !subcategories.includes(subcategory)) setSubcategory(""); }, [subcategory, subcategories]);
  useEffect(() => { setPreviewCount(null); }, [filter, startDate, endDate, courseType, subcategory]);
  const savePreset = () => {
    const name = presetName.trim();
    if (!name || !columnKeys.length) { toast.error("請先輸入名稱並選擇至少一個欄位"); return; }
    if (presets.length >= 8) { toast.error("最多可保存 8 組常用欄位"); return; }
    const preset = { id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, name, columnKeys };
    persistPresets([...presets, preset]); setPresetName(""); setSelectedPresetId(preset.id); toast.success("已保存常用欄位組合", { description: `下次可直接套用「${name}」。` });
  };
  const applyPreset = (presetId: string) => { setSelectedPresetId(presetId); const preset = presets.find(item => item.id === presetId); setRenamePresetName(preset?.name ?? ""); if (preset) setColumnKeys(preset.columnKeys); };
  const renamePreset = () => { if (!selectedPresetId) return; try { const preset = presets.find(item => item.id === selectedPresetId); const next = renameWrongQuestionCsvPreset(presets, selectedPresetId, renamePresetName); persistPresets(next); setRenamePresetName(next.find(item => item.id === selectedPresetId)?.name ?? ""); toast.success("常用欄位組合已重新命名", { description: `「${preset?.name ?? "欄位組合"}」已更新名稱。` }); } catch (error) { toast.error("重新命名未完成", { description: error instanceof Error ? error.message : "請稍後再試。" }); } };
  const deletePreset = () => { const preset = presets.find(item => item.id === selectedPresetId); if (!preset) return; persistPresets(presets.filter(item => item.id !== selectedPresetId)); setSelectedPresetId(""); setRenamePresetName(""); toast.success("已移除欄位組合", { description: `「${preset.name}」已從此帳號在此裝置的常用設定移除。` }); };
  const preview = () => {
    if (!user) { startLogin(); return; }
    if (exportData.isLoading || exportData.isFetching) { toast.info("正在同步個人錯題資料，請稍候再預覽。"); return; }
    try { setPreviewCount(filterWrongQuestionCsvItems(exportRows, filterOptions(filter)).length); } catch (error) { setPreviewCount(null); toast.error("無法預覽匯出範圍", { description: error instanceof Error ? error.message : "請確認日期設定。" }); }
  };
  return <div className="csv-export-controls"><div className="csv-export-buttons"><Button variant="outline" size="sm" aria-busy={exporting} disabled={!columnKeys.length || exporting} onClick={() => onExport(filterOptions(filter))}>{exporting ? <Spinner aria-label="正在建立 CSV"/> : <Download size={15}/>}<span>{exporting ? "正在建立 CSV…" : `匯出${filter === "全部" ? "錯題本" : filter} CSV`}</span></Button><Button variant="outline" size="sm" aria-busy={exporting} disabled={!hasPending || !columnKeys.length || exporting} onClick={() => onExport(filterOptions("待複習"))}>{exporting ? <Spinner aria-label="正在建立待複習 CSV"/> : <RotateCcw size={15}/>}<span>{exporting ? "正在建立 CSV…" : "快速匯出待複習"}</span></Button><Button variant="outline" size="sm" disabled={exportData.isLoading || exportData.isFetching} onClick={preview}>{previewCount === null ? "預覽符合題數" : `符合 ${previewCount} 題`}</Button></div><details className="csv-export-settings"><summary>CSV 欄位、日期與分類設定</summary><div className="csv-export-settings-body"><fieldset><legend>匯出欄位</legend><div className="csv-column-grid">{WRONG_QUESTION_CSV_COLUMNS.map(column => <label key={column.key}><input type="checkbox" checked={columnKeys.includes(column.key)} onChange={() => toggleColumn(column.key)}/>{column.label}</label>)}</div></fieldset><fieldset><legend>官方題庫分類篩選</legend><div className="csv-classification-range"><label>課程類型<select aria-label="CSV 匯出課程類型" value={courseType} onChange={event => setCourseType(event.target.value)}><option value="">全部課程</option>{courseTypes.map(type => <option value={type.id} key={type.id}>{type.label}</option>)}</select></label><label>次分類<select aria-label="CSV 匯出次分類" value={subcategory} onChange={event => setSubcategory(event.target.value)}><option value="">全部次分類</option>{subcategories.map(item => <option value={item} key={item}>{item}</option>)}</select></label></div></fieldset><div className="csv-date-range"><label>起始日期<input type="date" value={startDate} onChange={event => setStartDate(event.target.value)}/></label><label>結束日期<input type="date" value={endDate} onChange={event => setEndDate(event.target.value)}/></label></div><fieldset><legend>常用欄位組合</legend><div className="csv-preset-save"><input aria-label="欄位組合名稱" value={presetName} maxLength={32} placeholder="例如：考前精簡版" onChange={event => setPresetName(event.target.value)}/><Button variant="outline" size="sm" disabled={!columnKeys.length} onClick={savePreset}>保存目前欄位</Button></div>{presets.length ? <><div className="csv-preset-apply"><select aria-label="已保存的欄位組合" value={selectedPresetId} onChange={event => applyPreset(event.target.value)}><option value="">選擇常用組合</option>{presets.map(preset => <option value={preset.id} key={preset.id}>{preset.name}（{preset.columnKeys.length} 欄）</option>)}</select><Button variant="ghost" size="sm" disabled={!selectedPresetId} onClick={deletePreset}>刪除組合</Button></div><div className="csv-preset-rename"><input aria-label="重新命名欄位組合" value={renamePresetName} maxLength={32} disabled={!selectedPresetId} placeholder="選擇組合後可重新命名" onChange={event => setRenamePresetName(event.target.value)}/><Button variant="outline" size="sm" disabled={!selectedPresetId || !renamePresetName.trim()} onClick={renamePreset}>更新名稱</Button></div></> : <p className="csv-preset-empty">尚未保存欄位組合；設定好後可在此快速套用。</p>}</fieldset><div className="csv-setting-actions"><Button variant="ghost" size="sm" onClick={() => setColumnKeys(getDefaultWrongQuestionCsvColumns())}>全選欄位</Button><Button variant="ghost" size="sm" onClick={() => { setStartDate(""); setEndDate(""); setCourseType(""); setSubcategory(""); }}>清除篩選</Button></div></div></details></div>
}
function StatsPanel({ attempts, stats, starredStats, wrongProgress }: any) { const overall = stats?.totalAnswered ? Math.round(stats.totalCorrect / stats.totalAnswered * 100) : 0; const lastReviewed = starredStats?.lastReviewedAt ? new Date(starredStats.lastReviewedAt).toLocaleDateString("zh-TW", { month: "numeric", day: "numeric" }) : "尚未複習"; const reminderText = starredStats?.dueCount ? `${starredStats.dueCount} 題今日／已到期` : starredStats?.upcomingCount ? `${starredStats.upcomingCount} 題將在 7 日內到期` : "目前沒有待處理提醒"; return <div className="panel-wrap"><div className="section-heading"><div className="eyebrow">統計</div><h2>看見自己的進步。</h2><p>歷次測驗紀錄會在完成後自動同步。</p></div><div className="metric-row"><Metric icon={<BookOpenCheck/>} label="總答題數" value={stats?.totalAnswered ?? "—"}/><Metric icon={<CheckCircle2/>} label="總正確率" value={stats ? `${overall}%` : "—"}/><Metric icon={<History/>} label="歷史回合" value={attempts.length}/></div><Card className="wrong-progress-card"><CardContent><div><div className="eyebrow">錯題複習進度</div><h3>{wrongProgress?.completionRate ?? 0}% 已熟悉</h3><p>{wrongProgress?.mastered ?? 0} / {wrongProgress?.total ?? 0} 題已標記熟悉</p></div><div className="last-reviewed"><span>最近錯題更新</span><strong>{wrongProgress?.lastReviewedAt ? new Date(wrongProgress.lastReviewedAt).toLocaleDateString("zh-TW", { month: "numeric", day: "numeric" }) : "尚未有紀錄"}</strong><small>{wrongProgress?.total ? `待複習 ${wrongProgress.pending} 題 · 累計錯誤 ${wrongProgress.totalWrongCount} 次` : "完成練習後會在這裡整理"}</small></div><div className="wrong-progress-detail"><span>最常錯課程</span><strong>{wrongProgress?.mostWrongCategory ?? "—"}</strong><small>{wrongProgress?.mostWrongCategory ? `${wrongProgress.mostWrongCategoryCount} 次錯誤` : "尚無資料"}</small></div></CardContent></Card><Card className="starred-stats-card"><CardContent><div><div className="eyebrow">星號複習進度</div><h3>{starredStats?.completionRate ?? 0}% 已完成</h3><p>{starredStats?.reviewedCount ?? 0} / {starredStats?.total ?? 0} 題至少複習一次</p></div><div className="last-reviewed"><span>最近複習</span><strong>{lastReviewed}</strong><small>{reminderText}</small></div></CardContent></Card><div className="admin-list">{Object.entries(stats?.bySubject ?? {}).map(([subject, value]: any) => <Card className="history-row" key={subject}><CardContent><span>{subject}</span><strong>{value.accuracy}%</strong><small>{value.correct}/{value.answered} 題答對</small></CardContent></Card>)}</div>{attempts.length ? attempts.map((a: any) => <Card className="history-row" key={a.id}><CardContent><span>{a.mode === "mock" ? "模擬考" : a.mode === "starred" ? "星號隨機測驗" : "練習"}</span><strong>{a.score} 分</strong><small>{a.correctCount}/{a.questionCount} 題答對</small></CardContent></Card>) : <div className="empty-state"><History size={28}/><h3>尚未有測驗紀錄</h3><p>完成第一回測驗後，這裡會顯示你的歷史成績。</p></div>}</div> }
function ReadingSettings({ fontScale, setFontScale, density, setDensity, onBack }: any) { return <div className="panel-wrap settings-panel"><button className="back-link" onClick={onBack}><ChevronLeft size={16}/> 回首頁</button><div className="section-heading"><div className="eyebrow">閱讀設定</div><h2>調整成你的節奏。</h2><p>設定會儲存在此裝置，下次開啟 App 會自動還原。</p></div><Card className="setup-card"><CardHeader><CardTitle>字級大小</CardTitle></CardHeader><CardContent><div className="setting-options" role="group" aria-label="字級大小"><Button variant={fontScale === 0.9 ? "default" : "outline"} onClick={() => setFontScale(0.9)}>較小</Button><Button variant={fontScale === 1 ? "default" : "outline"} onClick={() => setFontScale(1)}>標準</Button><Button variant={fontScale === 1.15 ? "default" : "outline"} onClick={() => setFontScale(1.15)}>較大</Button></div><p className="setting-preview">目前題目閱讀預覽：以官方題庫為核心，讓每一次作答都更接近目標。</p></CardContent></Card><Card className="setup-card"><CardHeader><CardTitle>排版密度</CardTitle></CardHeader><CardContent><div className="setting-options" role="group" aria-label="排版密度"><Button variant={density === "comfortable" ? "default" : "outline"} onClick={() => setDensity("comfortable")}>舒適</Button><Button variant={density === "compact" ? "default" : "outline"} onClick={() => setDensity("compact")}>緊湊</Button></div><p className="setting-preview">舒適模式增加卡片間距與行距；緊湊模式讓一個畫面容納更多資訊。</p></CardContent></Card></div> }

function AdminPanel({ isAdmin }: { isAdmin: boolean }) {
  const subcategoryOptions = ["AI 工具與生成式 AI", "Windows 與桌面作業系統", "Linux／Unix 作業系統", "網路與通訊", "儲存裝置與檔案系統", "電腦硬體與組裝", "待確認"];
  const [adminFilter, setAdminFilter] = useState<"needs-review" | "subcategory-pending" | "all">("subcategory-pending");
  const [search, setSearch] = useState(""); const [quickFilters, setQuickFilters] = useState<AdminPendingQuickFilter[]>([]); const [selectedQuestionIds, setSelectedQuestionIds] = useState<string[]>([]); const [batchSubcategory, setBatchSubcategory] = useState("Windows 與桌面作業系統"); const [batchStatus, setBatchStatus] = useState<"assigned" | "needs_manual_review">("assigned"); const [batchNotes, setBatchNotes] = useState(""); const [editing, setEditing] = useState<any>(null); const [explanation, setExplanation] = useState(""); const [correctOption, setCorrectOption] = useState<any>("A"); const [subcategory, setSubcategory] = useState("待確認"); const [subcategoryStatus, setSubcategoryStatus] = useState<"assigned" | "needs_manual_review">("needs_manual_review"); const [subcategoryNotes, setSubcategoryNotes] = useState("");
  const query = trpc.quiz.adminList.useQuery({ needsReviewOnly: adminFilter === "needs-review", subcategoryReviewOnly: adminFilter === "subcategory-pending" }, { enabled: isAdmin });
  const reviewSummary = trpc.quiz.adminReviewSummary.useQuery(undefined, { enabled: isAdmin });
  const reviewHistory = trpc.quiz.adminReviewHistory.useQuery(undefined, { enabled: isAdmin });
  const exportPending = trpc.quiz.adminExportPending.useQuery(undefined, { enabled: false });
  useEffect(() => { if (reviewSummary.isError) toast.error("審核完成率暫時無法載入", { description: "請重新整理後再試；分類資料不會因此變更。" }); }, [reviewSummary.isError]);
  useEffect(() => { if (reviewHistory.isSuccess && !reviewHistory.data?.length) toast.info("尚無可復原操作", { description: "完成第一筆批次分類更新後，這裡會提供可安全復原的操作紀錄。" }); }, [reviewHistory.isSuccess, reviewHistory.data]);
  const visibleQuestions = useMemo(() => filterAdminPendingQuestions(query.data ?? [], search, quickFilters), [query.data, search, quickFilters]);
  const quickFilterCounts = useMemo(() => getAdminPendingQuickFilterCounts(query.data ?? []), [query.data]);
  const countLabel = query.isLoading ? "載入中…" : query.isError ? "無法載入" : `${visibleQuestions.length} / ${query.data?.length ?? 0} 題`;
  const save = trpc.quiz.adminUpdate.useMutation({ onSuccess: () => { setEditing(null); query.refetch(); reviewSummary.refetch(); } });
  const batchSave = trpc.quiz.adminBatchUpdateSubcategory.useMutation({ onSuccess: result => { setSelectedQuestionIds([]); setBatchNotes(""); query.refetch(); reviewSummary.refetch(); reviewHistory.refetch(); toast.success("已批次更新分類", { description: `${result.updatedCount} 題已更新為「${batchSubcategory}」；官方題目與答案維持不變。` }); }, onError: () => toast.error("批次更新未完成", { description: "請確認選取題目後重試。" }) });
  const restoreBatch = trpc.quiz.adminRestoreReviewBatch.useMutation({ onSuccess: result => { query.refetch(); reviewSummary.refetch(); reviewHistory.refetch(); toast.success("已復原批次分類", { description: `${result.restoredCount} 題已回到操作前的次分類狀態；官方內容未變更。` }); }, onError: () => toast.error("無法復原此批次", { description: "此操作可能已復原，請重新整理操作歷程。" }) });
  const startEdit = (question: any) => { setEditing(question); setExplanation(question.explanation || ""); setCorrectOption(question.correctOption); setSubcategory(question.subcategory || "待確認"); setSubcategoryStatus(question.subcategoryStatus === "assigned" ? "assigned" : "needs_manual_review"); setSubcategoryNotes(question.subcategoryNotes || ""); };
  const toggleQuickFilter = (id: "all" | AdminPendingQuickFilter) => { if (id === "all") { setQuickFilters([]); return; } setQuickFilters(current => current.includes(id) ? current.filter(value => value !== id) : [...current, id]); };
  const toggleQuestion = (questionId: string) => setSelectedQuestionIds(current => current.includes(questionId) ? current.filter(id => id !== questionId) : [...current, questionId]);
  const visibleQuestionIds = visibleQuestions.map((question: any) => question.id); const allVisibleSelected = visibleQuestionIds.length > 0 && visibleQuestionIds.every(id => selectedQuestionIds.includes(id));
  const toggleVisibleSelection = () => setSelectedQuestionIds(current => allVisibleSelected ? current.filter(id => !visibleQuestionIds.includes(id)) : Array.from(new Set([...current, ...visibleQuestionIds])));
  const handleExportPending = async () => {
    const result = await exportPending.refetch();
    if (result.error || !result.data) { toast.error("匯出未完成", { description: "請稍後再試。" }); return; }
    const csv = buildPendingQuestionsCsv(result.data);
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
    const anchor = document.createElement("a"); anchor.href = url; anchor.download = `待確認分類題目_${new Date().toISOString().slice(0, 10)}.csv`; anchor.click(); URL.revokeObjectURL(url);
    toast.success("待確認題目已匯出", { description: `已下載 ${result.data.length} 題 CSV；不含任何官方內容修改。` });
  };
  if (!isAdmin) return <div className="empty-state"><ShieldCheck size={30}/><h3>需要 admin 權限</h3><p>此區域不對一般使用者開放。</p></div>;
  const summary = reviewSummary.data;
  return <div className="panel-wrap"><div className="section-heading"><div className="eyebrow">Admin only</div><h2>題庫管理</h2><p>官方答案仍以 PDF Source of Truth 為準；次分類可獨立安全調整。</p></div><section className="admin-review-dashboard" aria-label="分類審核進度"><div><div className="eyebrow">分類審核完成率</div><strong>{reviewSummary.isLoading ? "載入中…" : `${summary?.completionRate ?? 0}%`}</strong><p>已審核 {summary?.reviewed ?? 0} / {summary?.total ?? 0} 題 · 尚待確認 {summary?.pending ?? 0} 題</p><div className="admin-review-progress" aria-label={`分類審核完成率 ${summary?.completionRate ?? 0}%`}><i style={{ width: `${summary?.completionRate ?? 0}%` }}/></div></div><Button variant="outline" className="admin-export-button" disabled={exportPending.isFetching} onClick={handleExportPending}><Download size={16}/>{exportPending.isFetching ? "正在準備…" : "匯出待確認 CSV"}</Button></section>{reviewHistory.data?.length ? <section className="admin-review-history"><div className="admin-history-heading"><div><div className="eyebrow">近期批次操作</div><strong>可安全復原的分類更新</strong></div><Badge>{reviewHistory.data.length} 筆</Badge></div><div className="admin-history-list">{reviewHistory.data.map((batch: any) => { const questionCount = (() => { try { return JSON.parse(batch.questionIdsJson).length; } catch { return 0; } })(); return <article key={batch.id} className="admin-history-row"><div><strong>{batch.appliedSubcategory}</strong><p>{new Date(batch.createdAt).toLocaleString("zh-TW", { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" })} · {questionCount} 題 · {batch.appliedStatus === "assigned" ? "已分類" : "待確認"}</p>{batch.appliedNotes && <small>註記：{batch.appliedNotes}</small>}</div>{batch.restoredAt ? <Badge className="admin-restored-badge">已復原</Badge> : <Button variant="outline" size="sm" disabled={restoreBatch.isPending} onClick={() => restoreBatch.mutate({ batchId: batch.id })}><Undo2 size={14}/>{restoreBatch.isPending ? "復原中…" : "復原"}</Button>}</article>; })}</div></section> : null}{editing && <Card className="setup-card"><CardHeader><CardTitle>審核 {editing.id}</CardTitle></CardHeader><CardContent><label>正確答案<select value={correctOption} onChange={event => setCorrectOption(event.target.value)}>{["A", "B", "C", "D"].map(option => <option key={option}>{option}</option>)}</select></label><label>解析<textarea value={explanation} onChange={event => setExplanation(event.target.value)} rows={5}/></label><label>次分類<select value={subcategory} onChange={event => { const value = event.target.value; setSubcategory(value); if (value === "待確認") setSubcategoryStatus("needs_manual_review"); }}>{subcategoryOptions.map(option => <option key={option}>{option}</option>)}</select></label><label>分類狀態<select value={subcategoryStatus} onChange={event => setSubcategoryStatus(event.target.value as "assigned" | "needs_manual_review")}><option value="assigned">已分類</option><option value="needs_manual_review">待確認</option></select></label><label>分類註記<textarea value={subcategoryNotes} onChange={event => setSubcategoryNotes(event.target.value)} rows={3} maxLength={500} placeholder="例如：題幹跨主題，需人工決定主要分類"/></label><div className="mark-actions"><Button className="primary-cta" disabled={save.isPending} onClick={() => save.mutate({ questionId: editing.id, explanation, correctOption, subcategory, subcategoryStatus, subcategoryNotes })}>{save.isPending ? "儲存中…" : "儲存更新"}</Button><Button variant="outline" onClick={() => setEditing(null)}>取消</Button></div></CardContent></Card>}<div className="admin-toolbar"><Button variant={adminFilter === "subcategory-pending" ? "default" : "outline"} onClick={() => setAdminFilter("subcategory-pending")}>待確認分類</Button><Button variant={adminFilter === "needs-review" ? "default" : "outline"} onClick={() => setAdminFilter("needs-review")}>只看待審題目</Button><Button variant={adminFilter === "all" ? "default" : "outline"} onClick={() => setAdminFilter("all")}>全部題目</Button><Badge>{countLabel}</Badge><input className="admin-search" aria-label="搜尋待確認分類題目" value={search} onChange={event => setSearch(event.target.value)} placeholder="搜尋題號、題幹或分類註記"/></div>{adminFilter === "subcategory-pending" && <><div className="admin-quick-filters" aria-label="快速篩選關鍵字">{ADMIN_PENDING_QUICK_FILTERS.map(filter => { const active = filter.id === "all" ? !quickFilters.length : quickFilters.includes(filter.id as AdminPendingQuickFilter); return <Button key={filter.id} size="sm" variant={active ? "default" : "outline"} onClick={() => toggleQuickFilter(filter.id as "all" | AdminPendingQuickFilter)}>{filter.label}<Badge className="quick-filter-count">{quickFilterCounts[filter.id as "all" | AdminPendingQuickFilter]}</Badge></Button>; })}</div><p className="admin-filter-help">以下列出全部 {query.isLoading ? "" : query.data?.length ?? 0} 題待確認分類題目。可複選 Windows、Linux 等主題；多選會合併顯示任一符合關鍵字的題目，並可再搭配文字搜尋。</p><div className="admin-batch-toolbar"><Button size="sm" variant="outline" onClick={toggleVisibleSelection}>{allVisibleSelected ? "取消選取目前範圍" : `選取目前 ${visibleQuestionIds.length} 題`}</Button><span>已選 {selectedQuestionIds.length} 題</span>{selectedQuestionIds.length > 0 && <Button size="sm" variant="outline" onClick={() => setSelectedQuestionIds([])}>清除選取</Button>}</div>{selectedQuestionIds.length > 0 && <Card className="admin-batch-card"><CardContent><div><div className="eyebrow">批次審核</div><strong>將 {selectedQuestionIds.length} 題安全更新分類</strong><p>此操作僅更新次分類、分類狀態與註記，不會改動官方題幹、選項、答案或解析。</p></div><label>次分類<select value={batchSubcategory} onChange={event => setBatchSubcategory(event.target.value)}>{subcategoryOptions.map(option => <option key={option}>{option}</option>)}</select></label><label>分類狀態<select value={batchStatus} onChange={event => setBatchStatus(event.target.value as "assigned" | "needs_manual_review")}><option value="assigned">已分類</option><option value="needs_manual_review">待確認</option></select></label><label>批次註記<textarea value={batchNotes} onChange={event => setBatchNotes(event.target.value)} maxLength={500} rows={2} placeholder="例如：依 Windows 題幹批次確認"/></label><Button className="primary-cta" disabled={batchSave.isPending} onClick={() => batchSave.mutate({ questionIds: selectedQuestionIds, subcategory: batchSubcategory, subcategoryStatus: batchStatus, subcategoryNotes: batchNotes.trim() || undefined })}>{batchSave.isPending ? "批次儲存中…" : `批次儲存 ${selectedQuestionIds.length} 題`}</Button></CardContent></Card>}</>}{query.isError && <div className="empty-state"><ShieldCheck size={28}/><h3>目前無法載入題庫清單</h3><p>請確認 admin 登入狀態後重新整理頁面。</p></div>}<div className="admin-list">{visibleQuestions.map((question: any) => <Card key={question.id} className="admin-row"><CardContent><div><Checkbox aria-label={`選取 ${question.id}`} checked={selectedQuestionIds.includes(question.id)} onCheckedChange={() => toggleQuestion(question.id)} /><Badge className={question.needsReview ? "review-badge" : ""}>{question.needsReview ? "待審" : "已匯入"}</Badge><Badge className={question.subcategoryStatus === "needs_manual_review" ? "review-badge" : ""}>{question.subcategory || "待確認"}</Badge><h3>{question.id} · {question.text.slice(0, 120)}{question.text.length > 120 ? "…" : ""}</h3><p>正解：{question.correctOption} · {question.section}</p>{question.subcategoryStatus === "needs_manual_review" && <p className="admin-subcategory-note"><strong>待確認原因：</strong>{question.subcategoryNotes || "官方題幹未達單一分類信心門檻，保留人工判定。"}</p>}</div><Button variant="outline" size="sm" onClick={() => startEdit(question)}>{question.subcategoryStatus === "needs_manual_review" ? "審核分類" : "編輯"}</Button></CardContent></Card>)}</div>{!query.isLoading && !query.isError && !visibleQuestions.length && <div className="empty-state"><ShieldCheck size={28}/><h3>沒有符合條件的題目</h3><p>調整篩選或搜尋關鍵字後再試一次。</p></div>}</div> }

function AdminReviewStateNotice({ isAdmin }: { isAdmin: boolean }) {
  const reviewSummary = trpc.quiz.adminReviewSummary.useQuery(undefined, { enabled: isAdmin });
  const reviewHistory = trpc.quiz.adminReviewHistory.useQuery(undefined, { enabled: isAdmin });
  if (!isAdmin || (!reviewSummary.isLoading && !reviewSummary.isError && !reviewHistory.isLoading && !reviewHistory.isError && reviewHistory.data?.length)) return null;
  const retry = () => { reviewSummary.refetch(); reviewHistory.refetch(); };
  if (reviewSummary.isError) return <section className="admin-query-notice summary-error" role="alert"><div><strong>審核完成率目前無法載入</strong><p>資料尚未變更，下方不會以 0% 作為替代數值。</p></div><Button variant="outline" size="sm" onClick={retry}>重新載入</Button></section>;
  if (reviewSummary.isLoading || reviewHistory.isLoading) return <section className="admin-query-notice"><div><strong>正在同步分類審核資料</strong><p>完成率與可復原操作會在資料回傳後顯示。</p></div></section>;
  if (reviewHistory.isError) return <section className="admin-query-notice history-error" role="alert"><div><strong>復原操作歷程目前無法載入</strong><p>分類資料未受影響；請重新載入後再試。</p></div><Button variant="outline" size="sm" onClick={retry}>重新載入</Button></section>;
  return <section className="admin-query-notice history-empty"><div><strong>尚無可復原操作</strong><p>完成第一筆批次分類更新後，這裡會保留操作前的分類欄位，供你安全復原。</p></div></section>;
}
